// Re-forge the shipped pack items' dnd5e activities from their GMMC blueprints.
//   node tools/forge-pack-activities.mjs [--dry-run]
// The blueprint is the source of truth, so the activities are generated by the module's own
// builders rather than authored by hand. Run it after anything that changes what they emit,
// then `npm run pack`.
import { fileURLToPath } from "node:url";
import path from "node:path";
import fs from "node:fs";
import yaml from "js-yaml";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const dryRun = process.argv.includes("--dry-run");

// The floor module.json declares. Anything at or above 4.0.1 stops dnd5e rebuilding an activity on read.
const STAMPED_SYSTEM_VERSION = "5.3.2";
const FEATURE_TYPE = "monster";
const ITEM_PACKS = ["gmm-monster-powers", "gmm-monster-attacks", "gmm-monster-traits"];

/* Everything else on a feat is pre-activities dnd5e 3.1 and is dropped by the schema on read. */
const FEAT_SYSTEM_KEYS = new Set([
    "description", "identifier", "source", "advancement", "activities", "uses",
    "cover", "crewed", "enchant", "prerequisites", "properties", "requirements", "type"
]);

installShim();
const { default: Activities } = await import(`file://${path.join(root, "scripts/classes/Activities.js")}`);

let changed = 0;
let seen = 0;
for (const pack of ITEM_PACKS) {
    const dir = path.join(root, "src", "packs", pack);
    for (const file of fs.readdirSync(dir)) {
        const target = path.join(dir, file);
        const before = fs.readFileSync(target, "utf8");
        const doc = yaml.load(before);
        if (!doc?.flags?.gmm?.blueprint || doc._key?.startsWith("!folders!")) continue;
        // The pruning list below is the feat schema, so anything else would lose fields it needs.
        if (doc.type !== "feat") throw new Error(`${file} is a ${doc.type}, which this tool cannot prune`);
        seen++;
        forgeItem(doc);
        const after = yaml.dump(doc, { noRefs: true });
        if (after === before.replace(/\r\n/g, "\n")) continue;
        changed++;
        console.log(`${pack}/${file}`);
        if (!dryRun) fs.writeFileSync(target, after, "utf8");
    }
}
console.log(`\n${changed} of ${seen} items ${dryRun ? "would be rewritten" : "rewritten"}`);

/* -------------------------------------------- */

function forgeItem(doc) {
    // The blueprints predate typed durations, which the module otherwise re-migrates on every import.
    const duration = Activities.buildPreCreateUpdate(doc, shimItem(doc))?.["flags.gmm.blueprint.data.duration"];
    if (duration) doc.flags.gmm.blueprint.data.duration = duration;

    const update = Activities.buildActivityUpdate(shimItem(doc), doc.flags.gmm.blueprint);

    doc.system.activities ??= {};
    for (const [key, value] of Object.entries(update)) {
        const legacyReplace = key.match(/^system\.activities\.==(.+)$/);
        const legacyDelete = key.match(/^system\.activities\.-=(.+)$/);
        if (legacyReplace) doc.system.activities[legacyReplace[1]] = value;
        else if (legacyDelete) delete doc.system.activities[legacyDelete[1]];
    }
    doc.system.uses = update["system.uses"];
    for (const effect of update.effects ?? []) {
        const at = (doc.effects ??= []).findIndex(e => e?._id === effect._id);
        // The pack tool writes each embedded document under its own key and refuses one without it.
        if (at < 0) doc.effects.push({ ...effect, _key: `!items.effects!${doc._id}.${effect._id}` });
        else doc.effects[at] = { ...doc.effects[at], ...effect };
    }

    for (const key of Object.keys(doc.system)) {
        if (!FEAT_SYSTEM_KEYS.has(key)) delete doc.system[key];
    }
    // Blank, the item answers no compendium browser category filter.
    doc.system.type = { value: doc.system.type?.value || FEATURE_TYPE, subtype: doc.system.type?.subtype ?? "" };
    doc._stats.systemVersion = STAMPED_SYSTEM_VERSION;
}

/* The builders read a prepared document rather than the source data a pack file holds. */
function shimItem(doc) {
    const activities = doc.system?.activities ?? {};
    const effects = Array.isArray(doc.effects) ? doc.effects : [];
    const collection = new Map(effects.map(e => [e._id, { ...e, id: e._id }]));
    collection[Symbol.iterator] = collection.values.bind(collection);
    return {
        _source: { system: { activities }, effects, flags: doc.flags },
        system: { activities: new Map(Object.entries(activities)) },
        effects: collection,
        flags: doc.flags,
        getSheetId: () => "giffyglyph-monster-maker-continued.ActionSheet"
    };
}

/* -------------------------------------------- */

/* Enough of Foundry and dnd5e for the builders to run outside a world. Anything world-conditional
 * answers "absent", so nothing a given GM's module set decides gets baked into the pack. */
function installShim() {
    const getProperty = (obj, keyPath) => keyPath.split(".").reduce((o, k) => o?.[k], obj);

    globalThis.CONST = { ACTIVE_EFFECT_SHOW_ICON: { NEVER: 0, CONDITIONAL: 1, ALWAYS: 2 } };
    globalThis.CONFIG = {
        DND5E: {
            dieSteps: [4, 6, 8, 10, 12, 20, 100],
            // Only the keys matter: an absent shape reads as a single target and moves the area off the template.
            areaTargetTypes: Object.fromEntries(
                ["circle", "cone", "cube", "cylinder", "line", "radius", "sphere", "square", "wall"].map(k => [k, {}])
            )
        }
    };
    globalThis.Hooks = { on: () => {}, once: () => {} };
    globalThis.Roll = class {};
    globalThis.Item = class {};
    globalThis.fromUuidSync = () => null;

    globalThis.dnd5e = {
        utils: {
            staticID: id => (id.length >= 16 ? id.substring(0, 16) : id.padEnd(16, "0")),
            defaultUnits: () => "ft"
        }
    };

    globalThis.foundry = {
        abstract: { DataModel: class {} },
        data: { operators: null },
        utils: {
            deepClone: v => structuredClone(v),
            getProperty,
            hasProperty: (obj, keyPath) => getProperty(obj, keyPath) !== undefined,
            setProperty: (obj, keyPath, value) => {
                const keys = keyPath.split(".");
                const last = keys.pop();
                keys.reduce((o, k) => (o[k] ??= {}), obj)[last] = value;
            },
            mergeObject: (a, b) => ({ ...a, ...b }),
            isEmpty: v => !v || (Object.keys(v).length === 0),
            objectsEqual: (a, b) => JSON.stringify(a) === JSON.stringify(b),
            // A generated id would differ on every run, so the packs would never settle.
            randomID: () => { throw new Error("a pack cannot carry a generated id"); }
        }
    };

    const lang = JSON.parse(fs.readFileSync(path.join(root, "lang", "en.json"), "utf8"));
    globalThis.game = {
        release: { generation: 14 },
        version: "14.364",
        system: { version: STAMPED_SYSTEM_VERSION },
        modules: { get: () => null },
        settings: { get: () => undefined },
        i18n: {
            has: key => key in lang,
            localize: key => lang[key] ?? key,
            format: (key, data = {}) =>
                (lang[key] ?? key).replace(/\{(\w+)\}/g, (m, k) => (k in data ? data[k] : m))
        }
    };
}
